WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT ARRAY['x'::text, NULL::text] AS c0, 10.0::float8 AS c1, (SELECT MIN ('-1 month'::interval) FROM t0 AS a3) AS c2 FROM (SELECT * FROM t3 WHERE (SELECT count(*) FROM (SELECT (-1)::bigint AS c0, ({ 'a' : ((MAX ('2024-02-29'::date) OVER (PARTITION BY '{"k": 2, "a": [0]}'::jsonb) + 1) - '2024-01-01'::date), 'b' : '%'::text }).a AS c1 FROM (t4 POSITIONAL JOIN t1)) AS kb) >= 0) AS a1 WHERE (SELECT BOOL_AND (TRUE) FROM t4 AS a2) UNION ALL SELECT ARRAY['1'::text] AS c0, 0.0::float8 AS c1, '00:00:00.000001'::interval AS c2;
